/**
 * System notification: DSH event frame → toast text mapping only follows the browser side. The frame is
 * generated by the host side listening to the DSH host event (see host/notify-events.ts), and the incremental queue of
 * the browser polling / notify consumes this mapping. Desktop mode is the body of pets and does not implement repeated
 * notifications (pets are not equal to notifications, and "consistency on both ends" only restricts pet behavior).
 * Pure functions have no side effect: if the frame shape does not match or the type is not recognized, null will be
 * returned without bombing or error.
 * @module dsh-pet/src/shared/notify
 */
/** Notification icon file name (excluding extension); browser side spells complete URL: / dsh-pet-7340/pic /< name >. png. */
export const NOTIFY_ICONS = {
  done: 'notify-done',
  error: 'notify-error',
  truncated: 'notify-truncated',
  approval: 'notify-approval',
  question: 'notify-question',
  test: 'notify-test',
} as const;

/** The upper limit of text truncation length ( character ). */
export const MAX_BODY = 80;

/** The upper limit of truncation of the session name in the title (character): The name is only for identifying people. If it is too long, the event type will be squeezed out of the title line. */
const MAX_SESSION_NAME = 30;

/** Copy text is truncated (consistent with the pop-up window: only the first 80 characters are left if it is too long). */
export function truncate(text: string): string {
  return text.length > MAX_BODY ? text.slice(0, MAX_BODY) + '…' : text;
}

/** Session name → A name that can be put into the title: remove leading and trailing blanks and truncate; return undefined if there is no name. */
function sessionNameOf(sessionTitle: string | undefined): string | undefined {
  const name = sessionTitle?.trim();
  if (!name) return undefined;
  return name.length > MAX_SESSION_NAME ? name.slice(0, MAX_SESSION_NAME) + '…' : name;
}

/** Title in the form of "session name·event"; if there is no session name, only the event type is left. */
function composeTitle(sessionTitle: string | undefined, label: string): string {
  const name = sessionNameOf(sessionTitle);
  return name ? name + ' · ' + label : label;
}

/** Notification frame: A DSH event forwarded by the host side. */
export interface NotifyFrame {
  type: string;
  /**
   * The session that issued this notification is id; when you click the notification, you will jump to that session
   * accordingly. Events without session location (host/agent-error) do not have this field, and the consumer treats
   * the absence as "window only".
   */
  sessionId?: string;
  [key: string]: unknown;
}

/** The shape of the turn/end event in the frame. */
interface TurnEndEvent {
  type?: string;
  data?: {
    reason?: { kind?: string; error?: { message?: string } };
    /** The beginning of the last reply brought by the host; if not, the fallback will be empty. */
    text?: string;
  };
}

/**
 * Frame → toast copy; unrecognized type or non-elastic branch of turn/end (aborted, etc.) returns null.
 *
 * @param frame - Notification frame forwarded by the host side.
 * @param sessionTitle - The display name of the session to which this frame belongs; when it is present, the title
 * carries the session name, and users can identify which one it is even if they have multiple sessions open at the
 * same time.
 * If it cannot be retrieved, just pass undefined. The title fallback is fixed and does not affect the pop-up window.
 */
export function frameToToast(
  frame: NotifyFrame,
  sessionTitle?: string,
): { title: string; body: string; icon: string } | null {
  switch (frame.type) {
    case 'session/event': {
      const ev = (frame.event ?? {}) as TurnEndEvent;
      if (ev.type !== 'turn/end') return null;
      const kind = ev.data?.reason?.kind;
      if (kind === 'completed') {
        const text = typeof ev.data?.text === 'string' ? ev.data.text.trim() : '';
        // The title of the completion notification is the conversation name itself: the text already talks about "What
        // is this reply about?", and adding "Conversation Completed" is just a placeholder. When there are multiple
        // conversations, it squeezes out the identification information.
        return {
          title: sessionNameOf(sessionTitle) ?? '对话完成',
          body: text ? truncate(text) : '',
          icon: NOTIFY_ICONS.done,
        };
      }
      if (kind === 'error')
        return {
          title: composeTitle(sessionTitle, '生成失败'),
          body: ev.data?.reason?.error?.message ?? '',
          icon: NOTIFY_ICONS.error,
        };
      if (kind === 'max-tokens')
        return {
          title: composeTitle(sessionTitle, '输出被截断'),
          body: '已达到输出 token 上限',
          icon: NOTIFY_ICONS.truncated,
        };
      // aborted (user/parent agent cancellation), interrupted (crash recovery), etc.: no bounce
      return null;
    }
    case 'approval/requested': {
      const toolName = typeof frame.toolName === 'string' ? frame.toolName : '';
      const reason = typeof frame.reason === 'string' && frame.reason ? frame.reason : '';
      return {
        title: composeTitle(sessionTitle, '正在申请权限'),
        body: (toolName ? '工具「' + toolName + '」' : '') + (reason ? '：' + reason : ''),
        icon: NOTIFY_ICONS.approval,
      };
    }
    case 'question/requested': {
      const q =
        (Array.isArray(frame.questions) && (frame.questions as Array<{ question?: string }>)[0]?.question) || '';
      return { title: composeTitle(sessionTitle, '模型在等你回答'), body: q, icon: NOTIFY_ICONS.question };
    }
    case 'host/agent-error': {
      return {
        title: '生成失败',
        body: typeof frame.message === 'string' ? (frame.message as string) : '',
        icon: NOTIFY_ICONS.error,
      };
    }
    default:
      return null;
  }
}
